function asArray(values) {
  if (!values) return [];
  if (Array.isArray(values)) return values;
  if (typeof values.toArray === 'function') return values.toArray();
  if (typeof values.get === 'function' && typeof values.length === 'number') {
    const out = [];
    for (let i = 0; i < values.length; i += 1) out.push(values.get(i));
    return out;
  }
  if (values.buffer) return Array.from(values.buffer);
  return Array.from(values || []);
}

function labelsFromDisplayName(text) {
  const labels = {};
  const raw = String(text || '');
  const body = raw.startsWith('{') && raw.endsWith('}') ? raw.slice(1, -1) : raw;
  const regex = /([a-zA-Z0-9_]+)="([^"]*)"/g;
  let match;
  while ((match = regex.exec(body)) !== null) {
    labels[match[1]] = match[2];
  }
  return labels;
}

function findField(frame, names) {
  const wanted = names.map((name) => String(name).toLowerCase());
  return (frame.fields || []).find((field) => wanted.includes(String(field.name || '').toLowerCase()));
}

function valueField(frame) {
  return (frame.fields || []).find((field) => String(field.name || '').toLowerCase().startsWith('value')) ||
    (frame.fields || []).find((field) => field.type === 'number');
}

function shortLabel(name) {
  return String(name || '')
    .replace('home-mini-proxy nginx', 'nginx')
    .replace('server_docker', 'Server Docker')
    .replace('server_k3s', 'k3s')
    .replace('lab_server', 'Mac Studio')
    .replace('edge_or_redirect', 'Edge / Redirect');
}

function hashColor(text, palette) {
  let hash = 0;
  const value = String(text || 'unknown');
  for (let i = 0; i < value.length; i += 1) {
    hash = ((hash << 5) - hash + value.charCodeAt(i)) | 0;
  }
  return palette[Math.abs(hash) % palette.length];
}

function rowsFromTableFrames() {
  const rows = [];
  for (const frame of context.panel.data?.series || []) {
    const countryField = findField(frame, ['geoip_country_name', 'Country']);
    const ingressField = findField(frame, ['entrypoint', 'Ingress']);
    const runtimeField = findField(frame, ['route_runtime', 'Runtime']);
    const domainField = findField(frame, ['server_name', 'Domain']);
    const upstreamField = findField(frame, ['upstream_addr', 'Upstream']);
    const requestsField = findField(frame, ['Requests']) || valueField(frame);

    if (!ingressField || !runtimeField || !domainField || !upstreamField || !requestsField) {
      continue;
    }

    const countries = asArray(countryField?.values);
    const ingressValues = asArray(ingressField.values);
    const runtimes = asArray(runtimeField.values);
    const domains = asArray(domainField.values);
    const upstreams = asArray(upstreamField.values);
    const requests = asArray(requestsField.values);
    const rowCount = Math.max(ingressValues.length, runtimes.length, domains.length, upstreams.length, requests.length);

    for (let i = 0; i < rowCount; i += 1) {
      const value = Number(requests[i] || 0);
      if (!Number.isFinite(value) || value <= 0) continue;
      rows.push({
        country: countries[i] || 'Unknown',
        ingress: ingressValues[i] || 'home-mini-proxy nginx',
        runtime: runtimes[i] || 'unknown_runtime',
        domain: domains[i] || 'unknown-domain',
        upstream: upstreams[i] || 'direct / redirect',
        requests: value,
      });
    }
  }
  return rows;
}

function rowsFromLabelFrames() {
  const rows = [];
  for (const frame of context.panel.data?.series || []) {
    for (const field of frame.fields || []) {
      const labels = Object.assign(
        {},
        labelsFromDisplayName(frame?.name),
        labelsFromDisplayName(field?.config?.displayNameFromDS),
        labelsFromDisplayName(field?.state?.displayName),
        labelsFromDisplayName(field?.name),
        frame?.labels || {},
        field?.labels || {}
      );
      if (!labels.entrypoint || !labels.route_runtime || !labels.server_name || !labels.upstream_addr) continue;
      const values = asArray(field.values);
      const value = Number(values[values.length - 1] || 0);
      if (!Number.isFinite(value) || value <= 0) continue;
      rows.push({
        country: labels.geoip_country_name || 'Unknown',
        ingress: labels.entrypoint,
        runtime: labels.route_runtime,
        domain: labels.server_name,
        upstream: labels.upstream_addr,
        requests: value,
      });
    }
  }
  return rows;
}

const textColor = context.grafana.theme.isDark ? '#d6dde8' : '#1f2937';
const mutedColor = context.grafana.theme.isDark ? '#8b98aa' : '#667085';
const tooltipBg = context.grafana.theme.isDark ? 'rgba(17, 24, 39, 0.96)' : 'rgba(255, 255, 255, 0.96)';
const tooltipBorder = context.grafana.theme.isDark ? '#2f3b52' : '#d0d5dd';
const palette = ['#8ecae6', '#ffb703', '#fb8500', '#90be6d', '#43aa8b', '#577590', '#f28482', '#b56576', '#6d597a', '#4d96ff', '#e76f51', '#2a9d8f'];
const runtimeColors = {
  server_docker: '#c6a628',
  server_k3s: '#5db3a6',
  lab_server: '#f28e2b',
  edge_or_redirect: '#98a2b3',
};

const chart = context.panel?.chart;
const chartHeight = Number(chart?.getHeight?.() || 420);
const compactCountryLimit = Math.max(8, Math.min(24, Math.floor((chartHeight - 84) / 18)));
const sankeyTop = chartHeight < 360 ? 8 : 18;
const sankeyBottom = chartHeight < 360 ? 10 : 22;
const sankeyNodeGap = chartHeight < 360 ? 6 : chartHeight < 480 ? 8 : 11;

function compactCountryRows(inputRows) {
  const totals = new Map();
  for (const row of inputRows) {
    const country = row.country || 'Unknown';
    totals.set(country, (totals.get(country) || 0) + row.requests);
  }

  if (totals.size <= compactCountryLimit) return inputRows;

  const keepCountries = new Set(
    Array.from(totals.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, compactCountryLimit)
      .map(([country]) => country)
  );

  return inputRows.map((row) => {
    const country = row.country || 'Unknown';
    return keepCountries.has(country) ? row : { ...row, country: 'Etc' };
  });
}

const rawRows = rowsFromTableFrames().concat(rowsFromLabelFrames());
const rows = compactCountryRows(rawRows);
const nodeMap = new Map();
const linkMap = new Map();

function addNode(name, depth, color) {
  if (!name || !String(name).trim()) return;
  if (!nodeMap.has(name)) {
    nodeMap.set(name, {
      name,
      depth,
      itemStyle: {
        color,
        borderColor: context.grafana.theme.isDark ? 'rgba(255,255,255,0.16)' : 'rgba(15,23,42,0.12)',
        borderWidth: 1,
      },
    });
  }
}

function addLink(source, target, value, color) {
  if (!source || !target || source === target || !Number.isFinite(value) || value <= 0) return;
  const key = `${source} -> ${target}`;
  const current = linkMap.get(key) || {
    source,
    target,
    value: 0,
    lineStyle: { color, opacity: 0.34, curveness: 0.55 },
  };
  current.value += value;
  linkMap.set(key, current);
}

for (const row of rows) {
  const countryColor = hashColor(row.country, palette);
  const runtimeColor = runtimeColors[row.runtime] || hashColor(row.runtime, palette);
  const domainColor = hashColor(row.domain, ['#d16ba5', '#86a8e7', '#5ffbf1', '#f9c74f', '#f8961e', '#90be6d']);
  const upstreamColor = hashColor(row.upstream, ['#3a86ff', '#06d6a0', '#8338ec', '#ff006e', '#2a9d8f', '#e9c46a']);

  addNode(row.country, 0, countryColor);
  addNode(row.ingress, 1, '#74a9cf');
  addNode(row.runtime, 2, runtimeColor);
  addNode(row.domain, 3, domainColor);
  addNode(row.upstream, 4, upstreamColor);

  addLink(row.country, row.ingress, row.requests, countryColor);
  addLink(row.ingress, row.runtime, row.requests, runtimeColor);
  addLink(row.runtime, row.domain, row.requests, domainColor);
  addLink(row.domain, row.upstream, row.requests, upstreamColor);
}

const nodes = Array.from(nodeMap.values());
const links = Array.from(linkMap.values()).sort((a, b) => b.value - a.value);

function selectedPathNames(seed, linkList) {
  const related = new Set([seed]);

  let frontier = new Set([seed]);
  while (frontier.size) {
    const next = new Set();
    for (const link of linkList) {
      if (frontier.has(link.target) && !related.has(link.source)) {
        related.add(link.source);
        next.add(link.source);
      }
    }
    frontier = next;
  }

  frontier = new Set([seed]);
  while (frontier.size) {
    const next = new Set();
    for (const link of linkList) {
      if (frontier.has(link.source) && !related.has(link.target)) {
        related.add(link.target);
        next.add(link.target);
      }
    }
    frontier = next;
  }

  return related;
}

if (chart) {
  chart.off('click');
  chart.on('click', (params) => {
    if (params?.seriesType !== 'sankey') return;
    chart.dispatchAction({ type: 'downplay', seriesIndex: 0 });

    const name = params.dataType === 'edge'
      ? (params.data?.target || params.data?.source)
      : params.name;

    if (!name || chart.__trafficFlowSankeySelected === name) {
      chart.__trafficFlowSankeySelected = undefined;
      return;
    }

    chart.__trafficFlowSankeySelected = name;
    for (const nodeName of selectedPathNames(name, links)) {
      chart.dispatchAction({ type: 'highlight', seriesIndex: 0, name: nodeName });
    }
  });
}

if (!nodes.length || !links.length) {
  const frames = context.panel.data?.series || [];
  const fieldCount = frames.reduce((sum, frame) => sum + (frame.fields?.length || 0), 0);
  const fields = frames.flatMap((frame) => (frame.fields || []).map((field) => field.name)).join(', ');
  return {
    backgroundColor: 'transparent',
    title: {
      text: `No Sankey rows. frames=${frames.length}, fields=${fieldCount}`,
      subtext: fields,
      left: 'center',
      top: 'middle',
      textStyle: { color: mutedColor, fontSize: 14, fontWeight: 500 },
      subtextStyle: { color: mutedColor, fontSize: 11 },
    },
  };
}

return {
  backgroundColor: 'transparent',
  animation: true,
  animationDuration: 800,
  animationEasing: 'cubicOut',
  tooltip: {
    trigger: 'item',
    triggerOn: 'mousemove',
    confine: true,
    backgroundColor: tooltipBg,
    borderColor: tooltipBorder,
    borderWidth: 1,
    padding: [10, 12],
    textStyle: { color: textColor, fontSize: 12 },
    formatter: (params) => {
      if (params.dataType === 'edge') {
        return `<b>${shortLabel(params.data.source)}</b><br/>to ${shortLabel(params.data.target)}<br/><span style="color:${mutedColor}">${Number(params.data.value).toLocaleString()} requests</span>`;
      }
      return `<b>${shortLabel(params.name)}</b>`;
    },
  },
  series: [
    {
      type: 'sankey',
      name: 'Traffic flow',
      left: 40,
      right: 32,
      top: sankeyTop,
      bottom: sankeyBottom,
      nodeWidth: 30,
      nodeGap: sankeyNodeGap,
      nodeAlign: 'justify',
      layoutIterations: 96,
      draggable: true,
      emphasis: {
        focus: 'adjacency',
        itemStyle: { borderWidth: 2, shadowBlur: 16 },
        lineStyle: { opacity: 0.9 },
      },
      blur: { itemStyle: { opacity: 0.16 }, lineStyle: { opacity: 0.045 } },
      label: {
        show: true,
        position: 'right',
        distance: 6,
        formatter: (params) => shortLabel(params.name),
        color: '#ffffff',
        fontFamily: 'Inter, SF Pro Display, Segoe UI, sans-serif',
        fontSize: 12,
        fontWeight: 750,
        overflow: 'truncate',
        width: chartHeight < 360 ? 118 : 142,
      },
      itemStyle: {
        borderRadius: 3,
        shadowBlur: 10,
        shadowColor: context.grafana.theme.isDark ? 'rgba(0,0,0,0.35)' : 'rgba(15,23,42,0.14)',
      },
      lineStyle: { color: 'gradient', opacity: 0.38, curveness: 0.56 },
      levels: [
        { depth: 0, label: { fontSize: 12, fontWeight: 700 }, lineStyle: { opacity: 0.24 } },
        { depth: 1, label: { fontSize: 14, fontWeight: 800 }, lineStyle: { opacity: 0.40 } },
        { depth: 2, label: { fontSize: 14, fontWeight: 800 }, lineStyle: { opacity: 0.48 } },
        { depth: 3, label: { fontSize: 12, fontWeight: 750 }, lineStyle: { opacity: 0.50 } },
        { depth: 4, label: { fontSize: 12, fontWeight: 750 }, lineStyle: { opacity: 0.56 } },
      ],
      data: nodes,
      links,
    },
  ],
};
